// Mimics the default WithAutomaticReconnect() policy: wait 0, 2, 10 and 30 seconds
// before the 1st..4th retry, then stop retrying. The server is down until t = 20 s,
// and each connection attempt is assumed to finish instantly.
TimeSpan?[] delays = { TimeSpan.Zero, TimeSpan.FromSeconds(2), TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(30), null };
double clock = 0;
for (int attempt = 0; ; attempt++)
{
    TimeSpan? next = delays[attempt];
    if (next is null) { Console.WriteLine($"t={clock}s: Closed"); break; }
    clock += next.Value.TotalSeconds;
    bool serverUp = clock >= 20;
    Console.WriteLine($"t={clock}s: retry {attempt + 1} {(serverUp ? "Reconnected" : "failed")}");
    if (serverUp) break;
}

using System.Text.Json;

// Bytes received so far on a SignalR connection that uses the JSON hub protocol.
const char RS = '\u001e';
string received = "{}" + RS
    + "{\"type\":6}" + RS
    + "{\"type\":1,\"target\":\"msg\",\"arguments\":[\"hi\",2]}" + RS
    + "{\"type\":1,\"target\":\"msg\",\"argu";

string[] parts = received.Split(RS);
for (int i = 0; i < parts.Length - 1; i++)
{
    using var doc = JsonDocument.Parse(parts[i]);
    var root = doc.RootElement;
    if (!root.TryGetProperty("type", out var type)) { Console.WriteLine("handshake response"); continue; }
    string text = type.GetInt32() switch
    {
        1 => $"Invocation {root.GetProperty("target").GetString()} ({root.GetProperty("arguments").GetArrayLength()} args)",
        6 => "Ping",
        7 => "Close",
        _ => "Other"
    };
    Console.WriteLine(text);
}
Console.WriteLine($"buffered: {parts[^1].Length} chars");

// Hand-written protobuf encoding of a single varint (wire type 0) field.
static byte[] Varint(ulong v)
{
    var bytes = new List<byte>();
    do
    {
        byte b = (byte)(v & 0x7F);
        v >>= 7;
        if (v != 0) b |= 0x80;
        bytes.Add(b);
    } while (v != 0);
    return bytes.ToArray();
}

static string Field(int number, ulong value) =>
    Convert.ToHexString(Varint((ulong)((number << 3) | 0)).Concat(Varint(value)).ToArray());

Console.WriteLine(Field(1, 150));
Console.WriteLine(Field(15, 1));
Console.WriteLine(Field(16, 1));
Console.WriteLine(Field(2, 300));

using System.Buffers.Binary;

// gRPC length-prefixed message: 1 byte compressed flag + 4 byte big-endian length + payload.
static byte[] Frame(byte[] message)
{
    var frame = new byte[5 + message.Length];
    frame[0] = 0; // not compressed
    BinaryPrimitives.WriteUInt32BigEndian(frame.AsSpan(1, 4), (uint)message.Length);
    message.CopyTo(frame, 5);
    return frame;
}

Console.WriteLine(Convert.ToHexString(Frame(new byte[] { 0x08, 0x96, 0x01 })));
Console.WriteLine(Convert.ToHexString(Frame(Array.Empty<byte>())));

const int MaxReceive = 4 * 1024 * 1024; // the default receive limit
byte[] header = Frame(new byte[5_000_000])[..5];
uint length = BinaryPrimitives.ReadUInt32BigEndian(header.AsSpan(1));
Console.WriteLine($"{length} bytes -> {(length > MaxReceive ? "ResourceExhausted" : "OK")}");

// Service B receives a call with a 1000 ms deadline and forwards it to service C
// with deadline propagation, so C works against the same absolute deadline.
var t0 = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc);
DateTime deadline = t0.AddMilliseconds(1000);
DateTime now = t0;

(string Step, int Ms)[] steps =
{
    ("B parses request", 150),
    ("B checks cache", 300),
    ("C loads data", 400),
    ("C builds reply", 200),
};

foreach (var (step, ms) in steps)
{
    TimeSpan remaining = deadline - now;
    if (ms > remaining.TotalMilliseconds)
    {
        Console.WriteLine($"{step}: cancelled after {remaining.TotalMilliseconds} ms -> DeadlineExceeded");
        break;
    }
    now = now.AddMilliseconds(ms);
    Console.WriteLine($"{step}: done, {(deadline - now).TotalMilliseconds} ms left");
}
